const form=document.querySelector('#smtp-form'),message=document.querySelector('#smtp-message');async function api(options={}){const response=await fetch('/api/admin/smtp-settings',{cache:'no-store',...options}),data=await response.json().catch(()=>({}));if(response.status===401){location.href='/admin/';throw new Error('Sessão expirada.')}if(!response.ok)throw new Error(data.error||'Não foi possível concluir.');return data}function values(){const v=Object.fromEntries(new FormData(form));v.porta=Number(v.porta);v.seguro=v.seguro==='true';v.ativo=v.ativo==='true';return v}async function load(){try{const {configuracao:c}=await api();for(const name of ['host','porta','usuario','remetenteNome','remetenteEmail','responderPara'])if(form.elements[name])form.elements[name].value=c[name]??'';form.elements.seguro.value=String(c.seguro);form.elements.ativo.value=String(c.ativo);form.elements.senha.placeholder=c.senhaConfigurada?'Configurada · deixe vazio para manter':'Informe a senha'}catch(error){message.textContent=error.message}}form.onsubmit=async e=>{e.preventDefault();message.textContent='';try{await api({method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(values())});message.textContent='Configuração salva com segurança.';form.elements.senha.value='';await load()}catch(error){message.textContent=error.message}};document.querySelector('#test').onclick=async()=>{message.textContent='Testando conexão…';try{const v=values();v.testar=true;const data=await api({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});message.textContent=data.mensagem}catch(error){message.textContent=error.message}};

const pushSummary=document.querySelector('#push-summary'),pushDevices=document.querySelector('#push-devices'),pushHistory=document.querySelector('#push-history');
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const formatDate=value=>value?new Date(value).toLocaleString('pt-BR'):'—';
async function pushApi(method='GET'){const response=await fetch('/api/admin/push-status',{method,cache:'no-store'}),data=await response.json().catch(()=>({}));if(response.status===401){location.href='/admin/';throw new Error('Sessão expirada.')}if(!response.ok)throw new Error(data.error||'Não foi possível consultar as notificações.');return data}
function pushReason(item){if(item.ultimo_erro)return item.ultimo_erro;const result=Array.isArray(item.resultado)?item.resultado[0]:null;if(result&&!result.ok)return `Firebase HTTP ${result.status}: ${result.resposta||'envio recusado'}`;return item.status==='ENVIADA'?'Entregue ao Firebase.':item.status==='SEM_DISPOSITIVO'?'Nenhum aparelho registrado para o usuário.':item.status==='AGUARDANDO_CONFIGURACAO'?'Firebase não configurado neste deploy.':'Aguardando processamento.'}
function renderPush(data){pushSummary.className=data.firebase.configurado?'push-ok':'push-error';pushSummary.textContent=data.firebase.configurado?`Firebase conectado ao projeto ${data.firebase.projectId}.`:`Firebase indisponível: ${data.firebase.motivo}`;pushDevices.innerHTML=data.dispositivos.length?data.dispositivos.map(item=>`<div class="push-item"><strong>${escapeHtml(item.nome_exibicao||item.login)} · ${escapeHtml(item.plataforma)}</strong><span>${item.ativo?'Ativo':'Inativo'} · último acesso ${formatDate(item.ultimo_acesso_em)}</span></div>`).join(''):'<div class="push-item push-error">Nenhum aparelho foi registrado pelo aplicativo.</div>';pushHistory.innerHTML=data.notificacoes.length?data.notificacoes.map(item=>`<div class="push-item"><strong>${escapeHtml(item.tipo)} · ${escapeHtml(item.status)}</strong><span>Atendimento #${escapeHtml(item.numero_atendimento||'—')} · ${formatDate(item.criado_em)}</span><span>${escapeHtml(pushReason(item))}</span></div>`).join(''):'<div class="push-item">Nenhuma tentativa de envio registrada.</div>'}
async function loadPush(method='GET'){pushSummary.className='';pushSummary.textContent=method==='POST'?'Enviando teste…':'Atualizando diagnóstico…';try{renderPush(await pushApi(method))}catch(error){pushSummary.className='push-error';pushSummary.textContent=error.message}}
document.querySelector('#push-test').onclick=()=>loadPush('POST');document.querySelector('#push-refresh').onclick=()=>loadPush();load();loadPush();
